import{_ as c,r as e,o as i,c as r,e as t,a as s,s as p,d as n}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Traits - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Attribute Manipulation","slug":"attribute-manipulation","link":"#attribute-manipulation","children":[{"level":3,"title":"Nullable","slug":"nullable","link":"#nullable","children":[]},{"level":3,"title":"Hashable","slug":"hashable","link":"#hashable","children":[]},{"level":3,"title":"Purgeable","slug":"purgeable","link":"#purgeable","children":[]},{"level":3,"title":"Encryptable","slug":"encryptable","link":"#encryptable","children":[]},{"level":3,"title":"Sluggable","slug":"sluggable","link":"#sluggable","children":[]},{"level":3,"title":"Base Identifier","slug":"base-identifier","link":"#base-identifier","children":[]}]},{"level":2,"title":"Sorting and Reordering","slug":"sorting-and-reordering","link":"#sorting-and-reordering","children":[{"level":3,"title":"Sortable","slug":"sortable","link":"#sortable","children":[]},{"level":3,"title":"Sortable Relation","slug":"sortable-relation","link":"#sortable-relation","children":[]},{"level":3,"title":"Simple Tree","slug":"simple-tree","link":"#simple-tree","children":[{"level":4,"title":"Rendering","slug":"rendering","link":"#rendering","children":[]}]},{"level":3,"title":"Nested Tree","slug":"nested-tree","link":"#nested-tree","children":[{"level":4,"title":"Creating a Root Node","slug":"creating-a-root-node","link":"#creating-a-root-node","children":[]},{"level":4,"title":"Inserting Nodes","slug":"inserting-nodes","link":"#inserting-nodes","children":[]},{"level":4,"title":"Deleting Nodes","slug":"deleting-nodes","link":"#deleting-nodes","children":[]},{"level":4,"title":"Getting the Nesting Level of a Node","slug":"getting-the-nesting-level-of-a-node","link":"#getting-the-nesting-level-of-a-node","children":[]},{"level":4,"title":"Moving Nodes Around","slug":"moving-nodes-around","link":"#moving-nodes-around","children":[]}]},{"level":3,"title":"Sluggable Tree","slug":"sluggable-tree","link":"#sluggable-tree","children":[]}]},{"level":2,"title":"Utility Functions","slug":"utility-functions","link":"#utility-functions","children":[{"level":3,"title":"Validation","slug":"validation","link":"#validation","children":[{"level":4,"title":"Enhanced Validation Rules","slug":"enhanced-validation-rules","link":"#enhanced-validation-rules","children":[]},{"level":4,"title":"Retrieving Validation Errors","slug":"retrieving-validation-errors","link":"#retrieving-validation-errors","children":[]},{"level":4,"title":"Overriding Validation","slug":"overriding-validation","link":"#overriding-validation","children":[]},{"level":4,"title":"Custom Error Messages","slug":"custom-error-messages","link":"#custom-error-messages","children":[]},{"level":4,"title":"Custom Attribute Names","slug":"custom-attribute-names","link":"#custom-attribute-names","children":[]},{"level":4,"title":"Dynamic Validation Rules","slug":"dynamic-validation-rules","link":"#dynamic-validation-rules","children":[]},{"level":4,"title":"Custom Validation Rules","slug":"custom-validation-rules","link":"#custom-validation-rules","children":[]}]},{"level":3,"title":"Soft Deleting","slug":"soft-deleting","link":"#soft-deleting","children":[{"level":4,"title":"Querying Soft Deleted Models","slug":"querying-soft-deleted-models","link":"#querying-soft-deleted-models","children":[]},{"level":4,"title":"Permanently Deleting Models","slug":"permanently-deleting-models","link":"#permanently-deleting-models","children":[]},{"level":4,"title":"Soft Deleting Relations","slug":"soft-deleting-relations","link":"#soft-deleting-relations","children":[]},{"level":4,"title":"Including Soft Deleted Relations","slug":"including-soft-deleted-relations","link":"#including-soft-deleted-relations","children":[]}]},{"level":3,"title":"Multisite","slug":"multisite","link":"#multisite","children":[]},{"level":3,"title":"Revisionable","slug":"revisionable","link":"#revisionable","children":[]},{"level":3,"title":"Translatable","slug":"translatable","link":"#translatable","children":[]},{"level":3,"title":"Defaultable","slug":"defaultable","link":"#defaultable","children":[]},{"level":3,"title":"User Footprints","slug":"user-footprints","link":"#user-footprints","children":[]}]}],"relativePath":"4.x/extend/database/traits.md","filePath":"4.x/extend/database/traits.md"}'),u={name:"4.x/extend/database/traits.md"};function d(k,a,g,h,m,b){const o=e("pre-heading"),l=e("post-heading");return i(),r("div",null,[t(o),a[0]||(a[0]=s("h1",null,"Traits",-1)),t(l),a[1]||(a[1]=p(`<p>Model traits are used to implement common functionality.</p><h2 id="attribute-manipulation"><a href="#attribute-manipulation" class="header-anchor">#</a> Attribute Manipulation</h2><h3 id="nullable"><a href="#nullable" class="header-anchor">#</a> Nullable</h3><p>Nullable attributes are set to <code>NULL</code> when left empty. To nullify attributes in your model, apply the <code>October\\Rain\\Database\\Traits\\Nullable</code> trait and declare a <code>$nullable</code> property with an array containing the attributes to nullify.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Nullable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$nullable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sku&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="hashable"><a href="#hashable" class="header-anchor">#</a> Hashable</h3><p>Hashed attributes are hashed immediately when the attribute is first set on the model. To hash attributes in your model, apply the <code>October\\Rain\\Database\\Traits\\Hashable</code> trait and declare a <code>$hashable</code> property with an array containing the attributes to hash.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Hashable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$hashable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="purgeable"><a href="#purgeable" class="header-anchor">#</a> Purgeable</h3><p>Purged attributes will not be saved to the database when a model is created or updated. To purge attributes in your model, apply the <code>October\\Rain\\Database\\Traits\\Purgeable</code> trait and declare a <code>$purgeable</code> property with an array containing the attributes to purge.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Purgeable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$purgeable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Use the <code>getOriginalPurgeValue</code> to find a value that was purged after the model was saved.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">getOriginalPurgeValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, use the <code>restorePurgedValues</code> method to restore all purged values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restorePurgedValues</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="encryptable"><a href="#encryptable" class="header-anchor">#</a> Encryptable</h3><p>Similar to the <code>Hashable</code> trait, encrypted attributes are encrypted when set but also decrypted when an attribute is retrieved. To encrypt attributes in your model, apply the <code>October\\Rain\\Database\\Traits\\Encryptable</code> trait and declare a <code>$encryptable</code> property with an array containing the attributes to encrypt.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Encryptable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$encryptable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;api_secret&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block warning"><p>Encrypted attributes are not compatible with <a href="./../system/models.html">jsonable attributes</a>.</p></div><h3 id="sluggable"><a href="#sluggable" class="header-anchor">#</a> Sluggable</h3><p>Slugs are meaningful codes that are commonly used in page URLs. To automatically generate a unique slug for your model, apply the <code>October\\Rain\\Database\\Traits\\Sluggable</code> trait and declare a <code>$slugs</code> property.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sluggable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>$slugs</code> property should be an array where the key is the destination column for the slug and the value is the source string used to generate the slug. In the above example, if the <code>name</code> column was set to <strong>Cheyenne</strong>, as a result the <code>slug</code> column would be set to <strong>cheyenne</strong>, <strong>cheyenne-2</strong>, or <strong>cheyenne-3</strong>, etc before the model is created.</p><p>To generate a slug from multiple sources, pass another array as the source value:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;last_name&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Slugs are only generated when a model first created. To override or disable this functionality, simply set the slug attribute manually:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Remy&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;custom-slug&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Slug will not be generated</span>
</code></pre></div><p>Use the <code>slugAttributes</code> method to regenerate slugs when updating a model:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">slugAttributes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="base-identifier"><a href="#base-identifier" class="header-anchor">#</a> Base Identifier</h3><p>Base identifiers add random base64 encoded identifiers to a model, used as random lookup keys that are immune to enumeration attacks. To add base identifiers to your model, apply the <code>October\\Rain\\Database\\Traits\\BaseIdentifier</code> trait.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Order</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>BaseIdentifier</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To add a <code>baseid</code> column to your table, you may use the <code>string</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;baseid&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Now, when a model is created, a unique random identifier will be generated and stored in the <code>baseid</code> column. This identifier is URL-safe and can be used for public-facing lookups instead of sequential IDs.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$order</span> <span class="token operator">=</span> <span class="token class-name static-context">Order</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Order&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">echo</span> <span class="token variable">$order</span><span class="token operator">-&gt;</span><span class="token property">baseid</span><span class="token punctuation">;</span> <span class="token comment">// Outputs something like: &quot;xK9mN2pL1qRs&quot;</span>
</code></pre></div><p>You may modify the column name used to store the base identifier by defining the <code>BASEID</code> constant.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">BASEID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_custom_baseid_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="sorting-and-reordering"><a href="#sorting-and-reordering" class="header-anchor">#</a> Sorting and Reordering</h2><h3 id="sortable"><a href="#sortable" class="header-anchor">#</a> Sortable</h3><p>Sorted models will store a number value in <code>sort_order</code> which maintains the sort order of each individual model in a collection. To add the <code>sort_order</code> column to your table, you may use the <code>integer</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To store a sort order for your models, apply the <code>October\\Rain\\Database\\Traits\\Sortable</code> trait and ensure that your schema has a column defined for it to use.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may modify the key name used to identify the sort order by defining the <code>SORT_ORDER</code> constant.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">SORT_ORDER</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_sort_order_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>setSortableOrder</code> method to set the orders on multiple records. The array contains the model identifiers in the sort order that they should appear.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If sorting a subset of records, the second array is used to provide a reference pool of sort order values. For example, the following assigns the sort order column as 100, 200 or 300.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="sortable-relation"><a href="#sortable-relation" class="header-anchor">#</a> Sortable Relation</h3><p>Sortable relations add sorting support to pivot relationships, such as <code>belongsToMany</code>. To add sorting to a pivot relationship, apply the <code>October\\Rain\\Database\\Traits\\SortableRelation</code> trait and define the <code>pivotSortable</code> option in your relation definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SortableRelation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;tags&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Tag</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;table&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme_blog_post_tag&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;pivotSortable&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;sort_order&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To add a <code>sort_order</code> column to your pivot table, you may use the <code>integer</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_blog_post_tag&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>setSortableRelationOrder</code> method to set the order of related records. The first argument is the relation name, the second is an array of record IDs in the desired order.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">setSortableRelationOrder</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;tags&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you want to use an incrementing pool starting from 1, pass <code>true</code> as the third argument.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">setSortableRelationOrder</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;tags&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, you can provide a specific array of sort order values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">setSortableRelationOrder</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;tags&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="simple-tree"><a href="#simple-tree" class="header-anchor">#</a> Simple Tree</h3><p>A simple tree model will use the <code>parent_id</code> column maintain a parent and child relationship between models. To add the <code>parent_id</code> column to your table, you may use the <code>integer</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To use the simple tree, apply the <code>October\\Rain\\Database\\Traits\\SimpleTree</code> trait.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This trait will automatically inject two <a href="./relations.html">model relations</a> called <code>parent</code> and <code>children</code>, it is the equivalent of the following definitions.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;parent&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;children&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>You do not need to define these relations yourself, however, you may modify the key name used to identify the parent by defining the <code>PARENT_ID</code> constant:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">PARENT_ID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_parent_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Collections of models that use this trait will return the type of <code>October\\Rain\\Database\\TreeCollection</code> which adds the <code>toNested</code> method. To build an eager loaded tree structure, return the records with the relations eager loaded.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">toNested</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="rendering"><a href="#rendering" class="header-anchor">#</a> Rendering</h4><p>In order to render all levels of items and their children, you can use recursive processing</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> renderChildren<span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> item<span class="token punctuation">.</span>children <span class="token operator">is</span> <span class="token operator">not</span> empty <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> child <span class="token operator">in</span> item<span class="token punctuation">.</span>children <span class="token delimiter punctuation">%}</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>name <span class="token delimiter punctuation">}}</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> _self_<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>child<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as nav <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> nav<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>category<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h3 id="nested-tree"><a href="#nested-tree" class="header-anchor">#</a> Nested Tree</h3>`,76)),a[2]||(a[2]=s("p",null,[n("The "),s("a",{href:"https://en.wikipedia.org/wiki/Nested_set_model",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("nested set model"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(" is an advanced technique for maintaining hierachies among models using "),s("code",null,"parent_id"),n(", "),s("code",null,"nest_left"),n(", "),s("code",null,"nest_right"),n(", and "),s("code",null,"nest_depth"),n(" columns. To add these columns to your table, you may use these methods inside a migration.")],-1)),a[3]||(a[3]=p(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_left&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_right&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_depth&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To use a nested set model, apply the <code>October\\Rain\\Database\\Traits\\NestedTree</code> trait. All of the features of the <code>SimpleTree</code> trait are inherently available in this model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="creating-a-root-node"><a href="#creating-a-root-node" class="header-anchor">#</a> Creating a Root Node</h4><p>By default, all nodes are created as roots:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$root</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Root category&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, you may find yourself in the need of converting an existing node into a root node:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">makeRoot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also nullify it&#39;s <code>parent_id</code> column which works the same as \`makeRoot&#39;.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token property">parent_id</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="inserting-nodes"><a href="#inserting-nodes" class="header-anchor">#</a> Inserting Nodes</h4><p>You can insert new nodes directly by the relation:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span> <span class="token operator">=</span> <span class="token variable">$root</span><span class="token operator">-&gt;</span><span class="token function">children</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 1&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Or use the <code>makeChildOf</code> method for existing nodes:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child2</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 2&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$child2</span><span class="token operator">-&gt;</span><span class="token function">makeChildOf</span><span class="token punctuation">(</span><span class="token variable">$root</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="deleting-nodes"><a href="#deleting-nodes" class="header-anchor">#</a> Deleting Nodes</h4><p>When a node is deleted with the <code>delete</code> method, all descendants of the node will also be deleted. Note that the delete <a href="./../system/models.html">model events</a> will not be fired for the child models.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="getting-the-nesting-level-of-a-node"><a href="#getting-the-nesting-level-of-a-node" class="header-anchor">#</a> Getting the Nesting Level of a Node</h4><p>The <code>getLevel</code> method will return current nesting level, or depth, of a node.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 0 when root</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">getLevel</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre></div><h4 id="moving-nodes-around"><a href="#moving-nodes-around" class="header-anchor">#</a> Moving Nodes Around</h4><p>There are several methods for moving nodes around:</p><ul><li><code>moveLeft()</code>: Find the left sibling and move to the left of it.</li><li><code>moveRight()</code>: Find the right sibling and move to the right of it.</li><li><code>moveBefore($otherNode)</code>: Move to the node to the left of ...</li><li><code>moveAfter($otherNode)</code>: Move to the node to the right of ...</li><li><code>makeChildOf($otherNode)</code>: Make the node a child of ...</li><li><code>makeRoot()</code>: Make current node a root node.</li></ul><h3 id="sluggable-tree"><a href="#sluggable-tree" class="header-anchor">#</a> Sluggable Tree</h3><p>The sluggable tree trait creates structured slugs, called full slugs, for hierarchical models. This is useful when you need URL paths that reflect the tree structure, such as <code>parent-slug/child-slug/grandchild-slug</code>. The model is assumed to have <code>parent</code> and <code>children</code> relations defined (typically via the <code>SimpleTree</code> or <code>NestedTree</code> traits).</p><p>To use the sluggable tree, apply the <code>October\\Rain\\Database\\Traits\\SluggableTree</code> trait along with a tree trait.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sluggable</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SluggableTree</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To add a <code>fullslug</code> column to your table, you may use the <code>string</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fullslug&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>fullSlugAttributes</code> method to calculate and update the full slug for a model and all its children. This should be called after making changes to the tree structure.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$category</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$category</span><span class="token operator">-&gt;</span><span class="token function">fullSlugAttributes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>For example, if you have the following structure:</p><ul><li>Electronics (slug: <code>electronics</code>) <ul><li>Phones (slug: <code>phones</code>) <ul><li>Smartphones (slug: <code>smartphones</code>)</li></ul></li></ul></li></ul><p>The full slugs would be:</p><ul><li>Electronics: <code>electronics</code></li><li>Phones: <code>electronics/phones</code></li><li>Smartphones: <code>electronics/phones/smartphones</code></li></ul><p>You may modify the column names by defining the <code>FULLSLUG</code> and <code>SLUG</code> constants.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">FULLSLUG</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_fullslug_column&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token constant">SLUG</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_slug_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="utility-functions"><a href="#utility-functions" class="header-anchor">#</a> Utility Functions</h2><h3 id="validation"><a href="#validation" class="header-anchor">#</a> Validation</h3><p>October CMS models uses the built-in <a href="./../services/validation.html">Validator class</a>. The validation rules are defined in the model class as a property named <code>$rules</code> and the class must use the trait <code>October\\Rain\\Database\\Traits\\Validation</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,16&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;alpha_num&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,8&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;confirmed&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;alpha_num&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,8&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may also use <a href="./../services/validation.html">array syntax</a> for validation rules.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Models validate themselves automatically when the <code>save</code> method is called.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Actual Person&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">email</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;a.person@example.tld&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;passw0rd&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// Returns false if model is invalid</span>
<span class="token variable">$success</span> <span class="token operator">=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>You can also validate a model at any time using the <code>validate</code> method.</p></div><h4 id="enhanced-validation-rules"><a href="#enhanced-validation-rules" class="header-anchor">#</a> Enhanced Validation Rules</h4><p>The <code>unique</code> validation rule is automatically configured and does not require a table name to be specified.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;unique&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>required</code> validation rule supports <strong>create</strong> and <strong>update</strong> modifiers to only apply when a model is created or updated respectively. The following is only required when the model does not already exist.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required:create&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="retrieving-validation-errors"><a href="#retrieving-validation-errors" class="header-anchor">#</a> Retrieving Validation Errors</h4><p>When a model fails to validate, a <code>Illuminate\\Support\\MessageBag</code> object is attached to the model. The object which contains validation failure messages. Retrieve the validation errors message collection instance with <code>errors</code> method or <code>$validationErrors</code> property. Retrieve all validation errors with <code>errors()-&gt;all()</code>. Retrieve errors for a <em>specific</em> attribute using <code>validationErrors-&gt;get(&#39;attribute&#39;)</code>.</p><div class="custom-block tip"><p>The Model leverages the <code>MessagesBag</code> object which has a <a href="./../services/validation.html">simple and elegant method</a> of formatting errors.</p></div><h4 id="overriding-validation"><a href="#overriding-validation" class="header-anchor">#</a> Overriding Validation</h4><p>The <code>forceSave</code> method validates the model and saves regardless of whether or not there are validation errors.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>

<span class="token comment">// Creates a user without validation</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="custom-error-messages"><a href="#custom-error-messages" class="header-anchor">#</a> Custom Error Messages</h4><p>Just like the Validator class, you can set custom error messages using the <a href="./../services/validation.html">same syntax</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The :attribute field is required.&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also add custom error messages to the array syntax for validation rules as well.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The url is required&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.url.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The url needs to be a valid url&#39;</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The anchor text is required&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In the above example you can write custom error messages to specific validation rules (here we used: <code>required</code>). Or you can use a <code>*</code> to select everything else (here we added a custom message to the <code>url</code> validation rule using the <code>*</code>).</p><h4 id="custom-attribute-names"><a href="#custom-attribute-names" class="header-anchor">#</a> Custom Attribute Names</h4><p>You may also set custom attribute names with the <code>$attributeNames</code> array.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attributeNames</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Email Address&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="dynamic-validation-rules"><a href="#dynamic-validation-rules" class="header-anchor">#</a> Dynamic Validation Rules</h4><p>You can apply rules dynamically by overriding the <code>beforeValidate</code> <a href="./../system/models.html">model event</a> method. Here we check if the <code>is_remote</code> attribute is <code>false</code> and then dynamically set the <code>latitude</code> and <code>longitude</code> attributes to be required fields.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeValidate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">is_remote</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;latitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;longitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="custom-validation-rules"><a href="#custom-validation-rules" class="header-anchor">#</a> Custom Validation Rules</h4><p>You can also create custom validation rules the <a href="./../services/validation.html">same way</a> you would for the <code>Validator</code> service.</p><h3 id="soft-deleting"><a href="#soft-deleting" class="header-anchor">#</a> Soft Deleting</h3><p>When soft deleting a model, it is not actually removed from your database. Instead, a <code>deleted_at</code> timestamp is set on the record. To enable soft deletes for a model, apply the <code>October\\Rain\\Database\\Traits\\SoftDelete</code> trait to the model and add the deleted_at column to your <code>$dates</code> property:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;deleted_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To add a <code>deleted_at</code> column to your table, you may use the <code>softDeletes</code> method from a migration:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">softDeletes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Now, when you call the <code>delete</code> method on the model, the <code>deleted_at</code> column will be set to the current timestamp. When querying a model that uses soft deletes, the &quot;deleted&quot; models will not be included in query results.</p><p>To determine if a given model instance has been soft deleted, use the <code>trashed</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">trashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="querying-soft-deleted-models"><a href="#querying-soft-deleted-models" class="header-anchor">#</a> Querying Soft Deleted Models</h4><h5>Including Soft Deleted Models</h5><p>As noted above, soft deleted models will automatically be excluded from query results. However, you may force soft deleted models to appear in a result set using the <code>withTrashed</code> method on the query:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>withTrashed</code> method may also be used on a <a href="./relations.html">relationship</a> query:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">history</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>Retrieving Only Soft Deleted Models</h5><p>The <code>onlyTrashed</code> method will retrieve <strong>only</strong> soft deleted models:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">onlyTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>Restoring Soft Deleted Models</h5><p>Sometimes you may wish to &quot;un-delete&quot; a soft deleted model. To restore a soft deleted model into an active state, use the <code>restore</code> method on a model instance:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also use the <code>restore</code> method in a query to quickly restore multiple models:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Restore a single model instance...</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Restore all related models...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="permanently-deleting-models"><a href="#permanently-deleting-models" class="header-anchor">#</a> Permanently Deleting Models</h4><p>Sometimes you may need to truly remove a model from your database. To permanently remove a soft deleted model from the database, use the <code>forceDelete</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Force deleting a single model instance...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Force deleting all related models...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="soft-deleting-relations"><a href="#soft-deleting-relations" class="header-anchor">#</a> Soft Deleting Relations</h4><p>When two related models have soft deletes enabled, you can cascade the delete event by defining the <code>softDelete</code> option in the <a href="./relations.html">relation definition</a>. In this example, if the user model is soft deleted, the comments belonging to that user will also be soft deleted.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;softDelete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>If the related model does not use the soft delete trait, it will be treated the same as the <code>delete</code> option and deleted permanently.</p></div><p>Under these same conditions, when the primary model is restored, all the related models that use the <code>softDelete</code> option will also be restored.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Restore the user and comments</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="including-soft-deleted-relations"><a href="#including-soft-deleted-relations" class="header-anchor">#</a> Including Soft Deleted Relations</h4><p>Soft deleted records are not included as part of relation lookups, however, you may include them by adding the <code>withTrashed</code> scope to the query.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;scope&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;withTrashed&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="multisite"><a href="#multisite" class="header-anchor">#</a> Multisite</h3><p>See the <a href="./../multisite/multisite.html">Multisite</a> article for multisite model support.</p><h3 id="revisionable"><a href="#revisionable" class="header-anchor">#</a> Revisionable</h3><p>October CMS models can record the history of changes in values by storing revisions. To store revisions for your model, apply the <code>October\\Rain\\Database\\Traits\\Revisionable</code> trait and declare a <code>$revisionable</code> property with an array containing the attributes to monitor for changes. You also need to define a <code>$morphMany</code> <a href="./relations.html">model relation</a> called <code>revision_history</code> that refers to the <code>System\\Models\\Revision</code> class with the name <code>revisionable</code>, this is where the revision history data is stored.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Revisionable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$revisionable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$morphMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;revision_history&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Revision</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;revisionable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>By default a maximum number of 500 records will be kept, however, this can be modified by declaring a <code>$revisionableLimit</code> property on the model with a new limit value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var int revisionableLimit as the maximum number records to keep.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$revisionableLimit</span> <span class="token operator">=</span> <span class="token number">8</span><span class="token punctuation">;</span>
</code></pre></div><p>The revision history can be accessed like any other relation:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$history</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">revision_history</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$history</span> <span class="token keyword">as</span> <span class="token variable">$record</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">field</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; updated &#39;</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;from &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">old_value</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;to &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">new_value</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The revision record optionally supports a user relationship using the <code>user_id</code> attribute. You may include a <code>getRevisionableUser</code> method in your model to keep track of the user that made the modification.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getRevisionableUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="translatable"><a href="#translatable" class="header-anchor">#</a> Translatable</h3><p>See the <a href="./../multisite/translatable.html">Translatable</a> article for model translation support.</p><h3 id="defaultable"><a href="#defaultable" class="header-anchor">#</a> Defaultable</h3><p>The defaultable trait adds default assignment to models using an <code>is_default</code> column. This is useful when you need to designate one record as the default among a collection, such as a default shipping method or payment gateway. To enable defaultable for a model, apply the <code>October\\Rain\\Database\\Traits\\Defaultable</code> trait.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">PaymentMethod</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Defaultable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To add an <code>is_default</code> column to your table, you may use the <code>boolean</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;payment_methods&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">boolean</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_default&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token constant boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When a model is saved with <code>is_default</code> set to <code>true</code>, all other records will automatically have their <code>is_default</code> set to <code>false</code>, ensuring only one default exists.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$method</span> <span class="token operator">=</span> <span class="token class-name static-context">PaymentMethod</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$method</span><span class="token operator">-&gt;</span><span class="token property">is_default</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token variable">$method</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// All other records will have is_default set to false</span>
</code></pre></div><p>Use the <code>makeDefault</code> method to explicitly make a record the default.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$method</span><span class="token operator">-&gt;</span><span class="token function">makeDefault</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the static <code>getDefault</code> method to retrieve the default record. If no default is found, the first record will automatically be made the default.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$defaultMethod</span> <span class="token operator">=</span> <span class="token class-name static-context">PaymentMethod</span><span class="token operator">::</span><span class="token function">getDefault</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="user-footprints"><a href="#user-footprints" class="header-anchor">#</a> User Footprints</h3><p>The user footprints trait automatically populates <code>created_user_id</code> and <code>updated_user_id</code> columns with the currently logged in backend user. This is useful for tracking which administrator created or last modified a record. To enable user footprints for a model, apply the <code>October\\Rain\\Database\\Traits\\UserFootprints</code> trait.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>UserFootprints</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To add the user footprint columns to your table, you may use the <code>integer</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Now, when a model is created, the <code>created_user_id</code> will be set to the current backend user. When a model is updated, the <code>updated_user_id</code> will be updated to the current backend user.</p><p>The trait automatically injects two <code>belongsTo</code> relations called <code>created_user</code> and <code>updated_user</code> that reference the backend user model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">echo</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">created_user</span><span class="token operator">-&gt;</span><span class="token property">full_name</span><span class="token punctuation">;</span> <span class="token comment">// Outputs the full name of the creator</span>
<span class="token keyword">echo</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">updated_user</span><span class="token operator">-&gt;</span><span class="token property">full_name</span><span class="token punctuation">;</span> <span class="token comment">// Outputs the full name of the last editor</span>
</code></pre></div><p>You may modify the column names by defining the <code>CREATED_USER_ID</code> and <code>UPDATED_USER_ID</code> constants.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">CREATED_USER_ID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_created_by_column&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token constant">UPDATED_USER_ID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_updated_by_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div>`,140))])}const y=c(u,[["render",d]]);export{f as __pageData,y as default};
